-- =============================================================================
-- Studuel — Migration 572 : SPORT 3e — LE CAHIER D'EXERCICES ET LES CONTRÔLES BLANCS
-- de la culture sportive (14/10/2026, docs/CADRAGE-SPORT.md). Deux parties générées,
-- collées à la suite : le cahier (scripts/exercices-sql.ts) puis les contrôles
-- (scripts/controles-sql.ts). À exécuter APRÈS la migration de cours de ce niveau
-- (les chapitres doivent exister : une ligne dont le chapitre manque est sautée).
-- =============================================================================

-- =============================================================================
-- 572 — LE CAHIER D'EXERCICES DE 3E
--
-- FICHIER GÉNÉRÉ par scripts/exercices-sql.ts depuis contenu/exercices/3e/ :
-- ne pas l'éditer à la main, corriger le JSON et régénérer :
--   node node_modules/jiti/lib/jiti-cli.mjs scripts/exercices-sql.ts --num 572 --niveau 3e --fichiers sport.culture,sport.culture2 > supabase/contenu/572_exercices_3e.sql
--
-- 30 exercices écrits et relus : pour chaque chapitre, trois exercices faits
-- comme une page de manuel (★ facile, ★★ moyen, ★★★ plus corsé), avec leurs
-- documents (cartes, graphiques, textes, schémas…) et leurs questions. Le
-- contenu public va dans `exercices`, les réponses et explications dans
-- `exercices_cles` (qu'aucun élève ne lit). Gemmes et XP selon les étoiles
-- (0/0/5 gemmes depuis la 557, 20/35/50 XP), réglables ensuite en base.
--
--   sport.culture            3 exercices · 1 chapitres
--   sport.culture2          27 exercices · 9 chapitres
--
-- L'identifiant d'un exercice est dérivé de (chapitre, position) : rejouer ce
-- fichier met les exercices à jour sans doublon, et garde les résultats des
-- élèves. Un exercice dont le chapitre n'existe pas en base est sauté.
--
-- PRÉREQUIS : 372 (le cahier). Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

DROP TABLE IF EXISTS pg_temp.exercices_seed;
CREATE TEMP TABLE exercices_seed AS
SELECT md5('exercice:' || v.chapter_id::text || ':' || v.position::text)::uuid AS id, v.*
FROM (VALUES
  ('bd49a667-d14a-5a45-affc-39f3164d15ad'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"La semaine d’Inès","competence":"lire-tableau","situation":"Inès, 14 ans, joue au hand en club et veut gagner en force pour ses tirs. Son entraîneur lui a écrit une semaine type, au poids du corps. Lis-la bien : chaque ligne a sa raison d’être.","documents":[{"id":"semaine","type":"tableau","titre":"La semaine type d’Inès","source":"Programme écrit pour l’exercice.","colonnes":["Jour","Séance","Séries × répétitions"],"lignes":[["Lundi","Pompes et tractions à l’élastique","3 × 10"],["Mardi","Repos","—"],["Mercredi","Squats et fentes","3 × 12"],["Jeudi","Gainage","3 × 40 s"],["Vendredi","Pompes et tractions à l’élastique","3 × 10"],["Samedi","Repos","—"],["Dimanche","Sortie vélo tranquille","1 h"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui dit combien de **séries et de répétitions** de squats Inès fait le mercredi.","aide":"Cherche la ligne « Mercredi », puis va jusqu’à la dernière colonne.","type":"zone","document":"semaine","multiple":false},{"enonce":"Combien de **squats** Inès fait-elle en tout le mercredi ?","aide":"3 séries de 12 répétitions : multiplie.","type":"nombre"},{"enonce":"Lundi et vendredi, Inès fait les mêmes exercices (pompes, tractions). Pourquoi l’entraîneur a-t-il laissé **trois jours** entre les deux ?","aide":"Relis le tableau : entre deux séances des mêmes muscles, il y a toujours au moins deux jours. Que fait le muscle pendant ce temps ?","type":"choix","options":[{"id":"a","texte":"Pour que ses muscles oublient le mouvement et le réapprennent"},{"id":"b","texte":"Pour que ses muscles aient le temps de se réparer : il faut au moins 48 h entre deux séances du même muscle"},{"id":"c","texte":"Parce qu’elle n’a pas le temps le mardi"},{"id":"d","texte":"Parce que les pompes ne font travailler aucun muscle"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Mercredi, Inès fait **3 × 12** : trois séries de douze squats (et de fentes). Douze répétitions, c’est dans la fourchette qui fait grossir un muscle."},{"cle":{"type":"nombre","valeur":36,"tolerance":0},"affichage":"36","explication":"3 × 12 = **36 squats**. Ce qui compte pour le muscle, ce n’est pas le total, c’est que chaque série aille jusqu’à la fatigue."},{"cle":{"type":"choix","ids":["b"]},"explication":"Après une séance, le muscle se **répare pendant 24 à 48 h** et se reconstruit un peu plus fort. Le retravailler avant, c’est casser ce qu’il n’a pas fini de remonter : c’est pour cela que l’entraîneur espace les séances des mêmes muscles."}]$ex$::jsonb),
  ('bd49a667-d14a-5a45-affc-39f3164d15ad'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Deux copains, deux méthodes","competence":"lire-graphique","situation":"Sami et Yanis se lancent un défi : faire le plus de pompes d’affilée en huit semaines. Sami s’entraîne deux fois par semaine avec deux jours de repos entre les séances. Yanis, lui, fait des pompes tous les jours, « pour aller plus vite ». Chaque dimanche, ils notent leur record.","documents":[{"id":"records","type":"graphique","forme":"courbe","titre":"Record de pompes d’affilée, semaine après semaine","source":"Chiffres imaginés pour l’exercice.","categories":["S1","S2","S3","S4","S5","S6","S7","S8"],"series":[{"nom":"Sami (2 séances par semaine)","valeurs":[12,14,16,18,21,24,27,30],"teinte":"violet"},{"nom":"Yanis (tous les jours)","valeurs":[12,15,18,17,16,15,14,13],"teinte":"corail"}],"axeY":{"titre":"Pompes d’affilée","min":0,"max":35,"pas":5},"axeX":{"titre":"Semaine"},"valeurs":false}],"questions":[{"enonce":"Combien de pompes d’affilée **Sami** réussit-il à la semaine 8 ?","aide":"Suis la courbe violette jusqu’à S8, puis lis la valeur sur l’axe vertical.","type":"nombre"},{"enonce":"Touche la **semaine** où Yanis atteint son meilleur record.","aide":"Cherche le point le plus haut de la courbe corail, puis touche la semaine juste en dessous.","type":"zone","document":"records","multiple":false},{"enonce":"Yanis s’entraîne tous les jours, sans repos. Que montre sa courbe à partir de la semaine 4 ?","aide":"Compare les deux courbes après S3 : laquelle monte, laquelle descend ? Et qui laisse du repos à ses muscles ?","type":"choix","options":[{"id":"a","texte":"Il stagne parce qu’il ne mange pas assez de sucre"},{"id":"b","texte":"Il a arrêté de s’entraîner"},{"id":"c","texte":"Il régresse : ses muscles n’ont plus le temps de se reconstruire entre deux séances"},{"id":"d","texte":"Il progresse plus vite que Sami"}],"multiple":false},{"enonce":"De combien de pompes **Sami** a-t-il progressé entre la semaine 1 et la semaine 8 ?","aide":"Lis sa valeur en S1 et en S8, puis fais la différence.","type":"nombre"}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"nombre","valeur":30,"tolerance":0},"affichage":"30","explication":"À la semaine 8, la courbe de Sami atteint **30 pompes**. Il a plus que doublé son record en deux mois."},{"cle":{"type":"zone","ids":["k2"]},"explication":"Le record de Yanis est à la **semaine 3** (18 pompes). Ensuite, sa courbe descend : son corps n’a plus le temps de récupérer."},{"cle":{"type":"choix","ids":["c"]},"explication":"Sans 48 h de repos, le muscle n’a pas le temps de se réparer : Yanis **s’épuise au lieu de progresser**, et sa courbe redescend. Sami, qui espace ses séances, continue de monter."},{"cle":{"type":"nombre","valeur":18,"tolerance":0},"affichage":"18","explication":"30 − 12 = **18 pompes** de plus. Deux séances par semaine, du repos entre les deux, et la régularité sur deux mois : c’est la recette."}]$ex$::jsonb),
  ('bd49a667-d14a-5a45-affc-39f3164d15ad'::uuid, 3, 3, 5, 50, 5,
   $ex${"titre":"Le programme « ultime » de Léo","competence":"raisonner","situation":"Léo, 14 ans, a trouvé sur internet un programme qui promet « des muscles en 30 jours ». Avant de le suivre, il le montre à son professeur d’EPS, qui lui tend la fiche des conseils aux jeunes sportifs. À toi de croiser les deux.","documents":[{"id":"programme","type":"fiche","modele":"affiche","entete":"PROGRAMME ULTIME 30 JOURS","sousTitre":"Trouvé sur internet par Léo","emoji":"💪","lignes":[{"texte":"Échauffement de 10 minutes avant chaque séance","id":"z1"},{"texte":"Pompes, squats, gainage au poids du corps","id":"z2"},{"texte":"5 séries de 3 répétitions à la charge maximale","id":"z3"},{"texte":"Le même circuit six jours sur sept","id":"z4"},{"texte":"3 shakers de protéines en poudre par jour","id":"z5"},{"texte":"8 heures de sommeil minimum","id":"z6"}],"pied":"Résultats garantis ou remboursés !","teinte":"corail"},{"id":"conseils","type":"tableau","titre":"Les conseils aux jeunes sportifs","source":"Fiche remise par le professeur d’EPS, rédigée pour l’exercice.","colonnes":["Réglage","Ce qui est conseillé avant la fin de la croissance"],"lignes":[["Répétitions par série","8 à 12, charge légère ou poids du corps"],["Séries","3 ou 4"],["Repos entre deux séances du même muscle","48 h au moins"],["Charge","jamais maximale : les cartilages de croissance sont fragiles"],["Protéines","celles de l’assiette suffisent (1,2 à 1,6 g par kilo et par jour)"],["Échauffement","10 minutes, à chaque séance"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la ligne du programme qui contredit la règle des **48 heures de repos**.","aide":"Combien de jours de repos le programme laisse-t-il entre deux circuits identiques ? Compare avec la ligne « Repos » des conseils.","type":"zone","document":"programme","multiple":false},{"enonce":"Range chaque ligne du programme : bonne pour Léo, ou à corriger ?","aide":"Passe chaque ligne du programme au crible du tableau des conseils : répétitions, charge, repos, protéines, échauffement.","type":"categories","categories":[{"id":"c0","texte":"Bonne pour Léo"},{"id":"c1","texte":"À corriger"}],"items":[{"id":"i0","texte":"3 shakers de protéines par jour"},{"id":"i1","texte":"8 heures de sommeil minimum"},{"id":"i2","texte":"5 séries de 3 répétitions à la charge maximale"},{"id":"i3","texte":"Le même circuit six jours sur sept"},{"id":"i4","texte":"Échauffement de 10 minutes"},{"id":"i5","texte":"Pompes, squats, gainage au poids du corps"}]},{"enonce":"Relie chaque ligne à corriger à la raison qui la rend mauvaise.","aide":"Cherche dans le tableau des conseils la ligne qui parle de repos, celle qui parle de charge, celle qui parle de protéines.","type":"association","gauche":[{"id":"g0","texte":"Le même circuit six jours sur sept"},{"id":"g1","texte":"5 séries de 3 répétitions à la charge maximale"},{"id":"g2","texte":"3 shakers de protéines par jour"}],"droite":[{"id":"d0","texte":"Les muscles n’ont pas 48 h pour se reconstruire"},{"id":"d1","texte":"Les protéines de l’assiette suffisent"},{"id":"d2","texte":"Les cartilages de croissance sont fragiles"}]},{"enonce":"Complète la règle que Léo doit retenir.","aide":"Les deux nombres sont dans le tableau des conseils : la ligne « Répétitions par série » et la ligne « Repos ».","type":"trous","segments":["Pour qu’un muscle grossisse, on vise des séries de ",0," répétitions et on attend au moins ",1," heures avant de le retravailler."],"banque":["1 à 3","48","8 à 12","6","24"]},{"enonce":"Le programme promet que « la charge maximale fait grossir plus vite ». Quel est le vrai risque pour Léo, à 14 ans ?","aide":"Relis la ligne « Charge » du tableau des conseils : pourquoi dit-elle « jamais maximale » ?","type":"choix","options":[{"id":"a","texte":"Oublier la technique des pompes"},{"id":"b","texte":"Aucun : à 14 ans, on récupère de tout"},{"id":"c","texte":"Grossir trop vite et perdre en vitesse"},{"id":"d","texte":"Abîmer ses cartilages de croissance : son squelette n’a pas fini de grandir"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z4"]},"explication":"« Le même circuit **six jours sur sept** » : les mêmes muscles sont retravaillés chaque jour, sans les 48 h qu’il leur faut pour se reconstruire."},{"cle":{"type":"categories","items":{"i0":"c1","i1":"c0","i2":"c1","i3":"c1","i4":"c0","i5":"c0"}},"explication":"Trois lignes sont à corriger : la **charge maximale** (interdite avant la fin de la croissance), les **shakers** (l’assiette suffit) et les **six jours sur sept** (pas de récupération). L’échauffement, le poids du corps et le sommeil sont justes."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g1":"d2"}},"explication":"**Six jours sur sept** → pas de récupération ; **charge maximale** → danger pour les cartilages de croissance ; **shakers** → inutiles, l’assiette apporte déjà 1,2 à 1,6 g de protéines par kilo."},{"cle":{"type":"trous","trous":[["8 a 12"],["48"]]},"affichage":"8 à 12 · 48","explication":"**8 à 12** répétitions par série, et **48 heures** de repos avant de retravailler le même muscle : c’est le temps que prend la réparation des fibres."},{"cle":{"type":"choix","ids":["d"]},"explication":"Avant la fin de la croissance, les **cartilages de croissance** aux extrémités des os sont fragiles : une charge maximale peut les abîmer. À 14 ans, on apprend le geste avec le poids du corps, et on ajoute la charge plus tard."}]$ex$::jsonb),
  ('d44a829c-4be5-53e3-a96c-a5d6d98a7b55'::uuid, 1, 1, 0, 20, 3,
   $ex${"titre":"Trois sportives, trois moteurs","competence":"lire-tableau","situation":"Au club d’athlétisme, Léa, Karim et Chloé ne s’entraînent pas du tout de la même façon. Leur entraîneur a résumé leurs trois portraits dans un tableau. Lis-le bien : chaque ligne raconte un moteur différent.","documents":[{"id":"portraits","type":"tableau","titre":"Trois portraits d’athlètes","source":"Portraits écrits pour l’exercice.","colonnes":["Sportif","Épreuve","Durée de l’effort","Entraînement typique"],"lignes":[["Léa","100 m","environ 12 secondes","sprints courts, récupération complète"],["Karim","Lancer du poids","moins d’une seconde","charges lourdes, technique parfaite"],["Chloé","Marathon","plus de 3 heures","longues sorties à allure modérée"]],"enteteLignes":true}],"questions":[{"enonce":"Touche la case qui donne la **durée de l’effort** de Chloé, la marathonienne.","aide":"Cherche la ligne de Chloé, puis la colonne « Durée de l’effort ».","type":"zone","document":"portraits","multiple":false},{"enonce":"Relie chaque sportif au moteur qu’il entraîne surtout.","aide":"Regarde la durée de l’effort et l’entraînement typique : un effort très court et explosif, un effort lourd, un effort très long.","type":"association","gauche":[{"id":"g0","texte":"Léa (100 m)"},{"id":"g1","texte":"Karim (lancer du poids)"},{"id":"g2","texte":"Chloé (marathon)"}],"droite":[{"id":"d0","texte":"La force"},{"id":"d1","texte":"L’endurance"},{"id":"d2","texte":"La vitesse"}]},{"enonce":"Chloé court plusieurs heures de suite. Quelles fibres musculaires lui sont les plus utiles ?","aide":"Pour durer longtemps, il faut des fibres qui se fatiguent peu.","type":"choix","options":[{"id":"a","texte":"Aucune : l’endurance ne dépend pas des muscles"},{"id":"b","texte":"Les fibres rapides (type II), qui produisent beaucoup de puissance"},{"id":"c","texte":"Les fibres lentes (type I), qui tiennent longtemps sans se fatiguer"},{"id":"d","texte":"Seulement les fibres du cœur"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["r2c2"]},"explication":"Chloé court **plus de 3 heures** : c’est un effort très long, typique de l’endurance."},{"cle":{"type":"association","paires":{"g1":"d0","g2":"d1","g0":"d2"}},"explication":"**Léa → vitesse** (sprints courts bien récupérés), **Karim → force** (charges lourdes), **Chloé → endurance** (efforts longs à allure modérée). Chaque moteur a sa méthode."},{"cle":{"type":"choix","ids":["c"]},"explication":"Les **fibres lentes** durent longtemps sans s’épuiser : le coureur de fond en a beaucoup. Les fibres rapides, elles, servent le sprinteur et le lanceur."}]$ex$::jsonb),
  ('d44a829c-4be5-53e3-a96c-a5d6d98a7b55'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"Le carnet de tests de Mathis","competence":"lire-tableau","situation":"Mathis a passé quatre tests physiques en septembre, puis les a refaits en décembre, dans les mêmes conditions. Il veut savoir si son entraînement a servi. Attention : pour certains tests, c’est le plus petit chiffre qui est le meilleur.","documents":[{"id":"tests","type":"tableau","titre":"Les résultats de Mathis","source":"Chiffres imaginés pour l’exercice.","colonnes":["Test","Septembre","Décembre"],"lignes":[["Saut en longueur sans élan (cm)",165,178],["Sprint sur 30 m (secondes)","5,6","5,3"],["Test navette (dernier palier atteint)",5,7],["Flexion du tronc (cm au-delà des pieds)",0,4]],"enteteLignes":true}],"questions":[{"enonce":"Relie chaque test à la qualité physique qu’il mesure.","aide":"Pense à ce que chaque test demande : sauter loin, courir vite, tenir des allers-retours, aller toucher plus loin.","type":"association","gauche":[{"id":"g0","texte":"Saut en longueur sans élan"},{"id":"g1","texte":"Sprint sur 30 m"},{"id":"g2","texte":"Test navette"},{"id":"g3","texte":"Flexion du tronc"}],"droite":[{"id":"d0","texte":"La souplesse"},{"id":"d1","texte":"La vitesse de départ"},{"id":"d2","texte":"L’endurance"},{"id":"d3","texte":"La détente des jambes"}]},{"enonce":"De combien de centimètres Mathis a-t-il amélioré son **saut en longueur** entre septembre et décembre ?","aide":"Soustrais le résultat de septembre à celui de décembre.","type":"nombre","unite":"cm"},{"enonce":"Au sprint sur 30 m, Mathis passe de 5,6 s à 5,3 s. Que peut-on dire ?","aide":"Au sprint, on mesure un temps : mieux vaut en mettre peu.","type":"choix","options":[{"id":"a","texte":"Il a régressé : le chiffre a diminué"},{"id":"b","texte":"Rien n’a changé, c’est seulement 0,3 s"},{"id":"c","texte":"On ne peut pas comparer deux résultats de sprint"},{"id":"d","texte":"Il a progressé : il met moins de temps pour parcourir la même distance"}],"multiple":false},{"enonce":"Touche la case qui donne le **palier atteint à la navette en décembre**.","aide":"Cherche la ligne « Test navette », puis la colonne « Décembre ».","type":"zone","document":"tests","multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"association","paires":{"g3":"d0","g1":"d1","g2":"d2","g0":"d3"}},"explication":"Le saut mesure la **détente**, le sprint de 30 m la **vitesse de départ**, la navette l’**endurance** et la flexion du tronc la **souplesse**."},{"cle":{"type":"nombre","valeur":13,"tolerance":0},"affichage":"13 cm","explication":"178 − 165 = **13 cm** de plus. Refaire le même test trois mois plus tard, c’est se comparer à soi-même."},{"cle":{"type":"choix","ids":["d"]},"explication":"Il court les 30 m en **0,3 s de moins** : c’est un vrai progrès. Au sprint, un chiffre plus petit est un meilleur résultat."},{"cle":{"type":"zone","ids":["r2c2"]},"explication":"En décembre, Mathis atteint le **palier 7**, contre le palier 5 en septembre : son endurance a progressé de deux paliers."}]$ex$::jsonb),
  ('d44a829c-4be5-53e3-a96c-a5d6d98a7b55'::uuid, 3, 3, 5, 50, 4,
   $ex${"titre":"Le stage du club d’athlé","competence":"raisonner","situation":"Le club d’athlétisme propose un samedi de stage aux jeunes de 14 ans. Quatre ateliers sont prévus, mais l’un d’eux n’est pas adapté. Croise le programme avec les conseils pour les 13-15 ans.","documents":[{"id":"programme","type":"fiche","modele":"affiche","entete":"STAGE D’ATHLÉ — 4 ATELIERS","sousTitre":"Programme du samedi, élèves de 14 ans","emoji":"🏃","lignes":[{"texte":"Atelier A : 6 sprints de 20 m, 2 minutes de récupération entre chaque","id":"z1"},{"texte":"Atelier B : 40 minutes de footing, on doit pouvoir parler","id":"z2"},{"texte":"Atelier C : squat à la charge maximale, 1 répétition","id":"z3"},{"texte":"Atelier D : lancers de ballon lesté léger, 3 séries de 10","id":"z4"}],"pied":"Programme écrit pour l’exercice.","teinte":"ambre"},{"id":"conseils","type":"tableau","titre":"Les conseils à 13-15 ans","source":"Fiche écrite pour l’exercice.","colonnes":["Moteur","Méthode adaptée","À 13-15 ans"],"lignes":[["Vitesse","sprints courts, récupération complète","à travailler beaucoup"],["Endurance","efforts longs à allure modérée","à travailler"],["Force","charges légères ou poids du corps, technique d’abord","jamais de charge maximale"]],"enteteLignes":true}],"questions":[{"enonce":"Touche l’atelier qui **ne convient pas** à des jeunes de 14 ans.","aide":"Regarde la ligne « Force » du tableau des conseils : que dit-elle de la charge maximale ?","type":"zone","document":"programme","multiple":false},{"enonce":"Range les trois ateliers qui restent selon le moteur qu’ils entraînent.","aide":"Sprints très courts, effort long à allure modérée, lancer d’une charge : un moteur pour chacun.","type":"categories","categories":[{"id":"c0","texte":"Vitesse"},{"id":"c1","texte":"Endurance"},{"id":"c2","texte":"Force"}],"items":[{"id":"i0","texte":"Atelier A : 6 sprints de 20 m, récupération complète"},{"id":"i1","texte":"Atelier D : lancers de ballon lesté léger"},{"id":"i2","texte":"Atelier B : 40 minutes de footing"}]},{"enonce":"Au total, quelle distance parcourent les sprints de l’**atelier A** ?","aide":"6 sprints de 20 m : multiplie.","type":"nombre","unite":"m"},{"enonce":"Pourquoi laisse-t-on **2 minutes de récupération** entre deux sprints de l’atelier A ?","aide":"Le tableau dit : « sprints courts, récupération complète ». À quoi sert une récupération complète ?","type":"choix","options":[{"id":"a","texte":"Pour repartir frais et rester vraiment vite à chaque sprint"},{"id":"b","texte":"Parce que l’endurance se travaille en se reposant"},{"id":"c","texte":"Pour s’échauffer entre deux sprints"},{"id":"d","texte":"Pour que les fibres lentes prennent le relais"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z3"]},"explication":"L’**atelier C** demande la charge maximale. À 14 ans, les os grandissent encore : on prépare la force avec le poids du corps et des charges légères, jamais à la limite."},{"cle":{"type":"categories","items":{"i0":"c0","i1":"c2","i2":"c1"}},"explication":"**A → vitesse** (sprints courts bien récupérés), **B → endurance** (effort long, allure modérée), **D → force** (une charge légère lancée, sans aller à la limite)."},{"cle":{"type":"nombre","valeur":120,"tolerance":0},"affichage":"120 m","explication":"6 × 20 = **120 m** de sprint en tout. C’est peu : l’intérêt est d’aller vite à chaque fois, pas d’en faire beaucoup."},{"cle":{"type":"choix","ids":["a"]},"explication":"Sans récupération complète, le sprinteur repart fatigué et ralentit : on ne travaille plus la vitesse. **Récupérer, c’est rester vite.**"}]$ex$::jsonb),
  ('2cd14700-c807-55c4-a500-c07adf0d5253'::uuid, 1, 1, 0, 20, 3,
