  ('0ee6bfe0-d940-505f-84a4-f7e8ece03dba'::uuid, 3, 3, 5, 50, 5,
   $ex${"titre":"Qui protège quoi ?","competence":"observer-schema","situation":"Le professeur d’EPS affiche le schéma d’un joueur vu de profil. Quatre points du corps sont signalés ; le tableau dit ce qui les menace et comment les protéger. À toi de relier les deux.","documents":[{"id":"corps","type":"schema","titre":"Quatre points fragiles","source":"Schéma simplifié, écrit pour l’exercice.","largeur":320,"hauteur":350,"elements":[{"forme":"cercle","cx":130,"cy":40,"r":20,"teinte":"gris","motif":"clair"},{"forme":"rect","x":105,"y":65,"l":50,"h":100,"arrondi":14,"teinte":"violet","motif":"clair"},{"forme":"rect","x":119,"y":165,"l":26,"h":75,"arrondi":10,"teinte":"violet","motif":"clair"},{"forme":"rect","x":124,"y":240,"l":20,"h":58,"arrondi":8,"teinte":"violet","motif":"clair"},{"forme":"ellipse","cx":152,"cy":322,"rx":38,"ry":10,"teinte":"violet","motif":"clair"},{"forme":"cercle","cx":105,"cy":115,"r":11,"teinte":"corail","motif":"plein","id":"z1","zone":true},{"forme":"cercle","cx":132,"cy":240,"r":11,"teinte":"corail","motif":"plein","id":"z2","zone":true},{"forme":"cercle","cx":134,"cy":298,"r":10,"teinte":"corail","motif":"plein","id":"z3","zone":true},{"forme":"cercle","cx":118,"cy":322,"r":9,"teinte":"corail","motif":"plein","id":"z4","zone":true}]},{"id":"tableau","type":"tableau","titre":"Menaces et protections","source":"Tableau écrit pour l’exercice.","colonnes":["Blessure ou risque","Zone","Réponse"],"lignes":[["Osgood-Schlatter (10 à 15 ans)","Genou","moins de sauts, on adapte"],["Sever (8 à 13 ans)","Talon","moins de course sur sol dur"],["Mal de dos","Dos","gainage : planche, gainage latéral"],["Entorse de cheville","Cheville","équilibre sur un pied"]],"enteteLignes":true}],"questions":[{"enonce":"Touche sur le schéma la zone touchée par la maladie d’**Osgood-Schlatter**.","aide":"Cherche cette maladie dans le tableau : quelle zone indique-t-il ?","type":"zone","document":"corps","multiple":false},{"enonce":"Touche sur le schéma la zone touchée par la maladie de **Sever**.","aide":"Le tableau donne la zone : le point est à l’arrière du pied.","type":"zone","document":"corps","multiple":false},{"enonce":"Sami, 9 ans, a mal au talon après chaque match. Laquelle de ces blessures est la plus probable ?","aide":"Croise la zone (talon) et l’âge typique de chaque maladie dans le tableau.","type":"choix","options":[{"id":"a","texte":"Une entorse de la cheville"},{"id":"b","texte":"Un mal de dos"},{"id":"c","texte":"La maladie d’Osgood-Schlatter"},{"id":"d","texte":"La maladie de Sever"}],"multiple":false},{"enonce":"Relie chaque moyen de prévention à la zone qu’il protège.","aide":"Reprends la dernière colonne du tableau, ligne par ligne.","type":"association","gauche":[{"id":"g0","texte":"Planche et gainage latéral"},{"id":"g1","texte":"Équilibre sur un pied"},{"id":"g2","texte":"Moins de sauts"},{"id":"g3","texte":"Moins de course sur sol dur"}],"droite":[{"id":"d0","texte":"La cheville"},{"id":"d1","texte":"Le dos"},{"id":"d2","texte":"Le talon"},{"id":"d3","texte":"Le genou"}]},{"enonce":"Avant un match, Paul fait un étirement statique de deux minutes pour « protéger » ses muscles. Qu’en penser ?","aide":"Les étirements statiques longs ont une place, mais laquelle ?","type":"choix","options":[{"id":"a","texte":"Cela remplace l’échauffement"},{"id":"b","texte":"Ça diminue la force un moment et ne prévient pas les blessures : mieux vaut s’échauffer en mouvement"},{"id":"c","texte":"C’est la meilleure protection qui existe"},{"id":"d","texte":"C’est dangereux pour le dos"}],"multiple":false}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["z2"]},"explication":"Osgood-Schlatter est une douleur de croissance **sous le genou**, fréquente entre 10 et 15 ans."},{"cle":{"type":"zone","ids":["z4"]},"explication":"La maladie de Sever est une douleur de croissance au **talon**, typique entre 8 et 13 ans."},{"cle":{"type":"choix","ids":["d"]},"explication":"Talon et 9 ans : c’est la **maladie de Sever** (8 à 13 ans). On adapte l’activité, on ne force pas."},{"cle":{"type":"association","paires":{"g1":"d0","g0":"d1","g3":"d2","g2":"d3"}},"explication":"**Gainage → dos**, **équilibre → cheville**, **moins de sauts → genou**, **moins de sol dur → talon**. Chaque zone fragile a sa réponse."},{"cle":{"type":"choix","ids":["b"]},"explication":"Avant l’effort, un étirement **statique long** n’empêche pas les blessures et diminue la force. On le garde pour après, et on s’échauffe en mouvement."}]$ex$::jsonb),
