  ('ae015207-9a1c-5548-8302-1d79a431baee'::uuid, 2, 2, 0, 35, 4,
   $ex${"titre":"La phrase de Coubertin","competence":"analyser-texte","situation":"Au CDI, Inès et Malo préparent un exposé sur Pierre de Coubertin. Ils s’aperçoivent que bien des choses qu’on croit savoir sont plus nuancées. Lis leur échange.","documents":[{"id":"echange","type":"dialogue","modele":"sms","titre":"Au CDI","source":"Dialogue écrit pour l’exercice.","participants":[{"nom":"Inès","emoji":"👧","cote":"gauche"},{"nom":"Malo","emoji":"👦","cote":"droite"}],"repliques":[{"qui":"Inès","texte":"J’ai lu : « L’important dans la vie n’est pas le triomphe mais le combat. » C’est de Coubertin, non ?"},{"qui":"Malo","texte":"Il l’a citée en 1908, mais il reprenait l’évêque américain Talbot."},{"qui":"Inès","texte":"Et la devise des Jeux, « plus vite, plus haut, plus fort » ?"},{"qui":"Malo","texte":"En latin : Citius, Altius, Fortius. Elle vient du dominicain Henri Didon, qui l’a lancée en 1891."},{"qui":"Inès","texte":"Donc Coubertin était favorable à tout le monde ?"},{"qui":"Malo","texte":"Non : il était opposé au sport féminin de compétition. C’est Alice Milliat qui a organisé les Jeux mondiaux féminins à Paris, en 1922."}]}],"questions":[{"enonce":"Touche le nom de celui dont **Coubertin reprend la phrase** sur le combat.","aide":"Cherche la réponse de Malo à propos de la phrase de 1908.","type":"zone","document":"echange","multiple":false},{"enonce":"Relie chaque personnage à ce qu’on lui doit.","aide":"Relis ce que Malo explique pour chaque nom.","type":"association","gauche":[{"id":"g0","texte":"Pierre de Coubertin"},{"id":"g1","texte":"Henri Didon"},{"id":"g2","texte":"Alice Milliat"},{"id":"g3","texte":"Ethelbert Talbot"}],"droite":[{"id":"d0","texte":"Les Jeux olympiques modernes (1896)"},{"id":"d1","texte":"Les Jeux mondiaux féminins (Paris, 1922)"},{"id":"d2","texte":"La phrase sur le combat, reprise en 1908"},{"id":"d3","texte":"La devise Citius, Altius, Fortius"}]},{"enonce":"Que montre l’échange à propos de Coubertin ?","aide":"Malo dit à la fois ce que Coubertin a fait et ce qu’il refusait.","type":"choix","options":[{"id":"a","texte":"On peut admirer ce qu’il a construit et reconnaître ses limites"},{"id":"b","texte":"Il a tout inventé seul, sans personne avant lui"},{"id":"c","texte":"Il s’est opposé à la création des Jeux"},{"id":"d","texte":"Il a toujours soutenu le sport féminin"}],"multiple":false},{"enonce":"Complète la traduction de la devise olympique.","aide":"Citius = rapide, Fortius = puissant. Il manque deux adjectifs.","type":"trous","segments":["« Citius, Altius, Fortius » signifie : plus ",0,", plus haut, plus ",1,"."],"banque":["fort","loin","grand","vite"]}]}$ex$::jsonb,
   $ex$[{"cle":{"type":"zone","ids":["m33"]},"explication":"Coubertin cite en 1908 un propos de l’évêque américain **Ethelbert Talbot**. La phrase est souvent résumée en « l’important, c’est de participer »."},{"cle":{"type":"association","paires":{"g0":"d0","g2":"d1","g3":"d2","g1":"d3"}},"explication":"Chacun a sa place : **Coubertin** les Jeux, **Didon** la devise, **Milliat** les Jeux féminins, **Talbot** la phrase sur le combat."},{"cle":{"type":"choix","ids":["a"]},"explication":"Coubertin a bâti les Jeux modernes, mais il était **opposé au sport féminin de compétition** : c’est ce qui a poussé Alice Milliat à organiser ses propres Jeux."},{"cle":{"type":"trous","trous":[["vite"],["fort"]]},"affichage":"vite · fort","explication":"La devise lancée par Henri Didon en 1891 veut dire « plus **vite**, plus haut, plus **fort** »."}]$ex$::jsonb),
