"},{"id":"c","texte":"Les étapes d’aujourd’hui sont bien plus courtes qu’en 1903"},{"id":"d","texte":"Les étapes d’aujourd’hui sont plus longues qu’en 1903"}],"multiple":false}]}$ex$::jsonb,
